DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.department_scorecards(date)'::regprocedure) INTO f; f:=replace(f,'month<=m AND status=''approved'' ORDER BY month DESC LIMIT 1','month=m AND status=''approved'' ORDER BY month DESC LIMIT 1'); EXECUTE f; SELECT pg_get_functiondef('public._department_actual(uuid,date,text)'::regprocedure) INTO f; f:=replace(f,'coalesce(l.contract_start,l.day0_date,l.launch_date)','coalesce(l.contract_signed_on,l.contract_start,l.day0_date,l.launch_date)'); f:=replace(f,'coalesce(contract_start,day0_date,launch_date)','coalesce(contract_signed_on,contract_start,day0_date,launch_date)'); f:=replace(f,'coalesce(change_kind,''new'') NOT IN (''upgrade'',''downgrade'',''renewal'')','coalesce(change_kind,''new'') NOT IN (''upgrade'',''downgrade'',''relaunch'',''plan_change'') AND previous_launch_id IS NULL'); EXECUTE f; END $$;